import { test, expect } from '@playwright/test';

test.describe('Form Auto-Save Draft Feature', () => {
  let formUrl: string;

  test.beforeEach(async ({ page }) => {
    formUrl = 'http://localhost:3000/form';
    await page.goto(formUrl);
    // Wait for form to be fully loaded
    await page.waitForLoadState('networkidle');
  });

  test('should auto-save form as draft every 30 seconds', async ({ page }) => {
    // Fill in form fields
    const nameInput = page.getByLabel('Name');
    const emailInput = page.getByLabel('Email');
    const messageInput = page.getByLabel('Message');

    await nameInput.fill('John Doe');
    await emailInput.fill('john@example.com');
    await messageInput.fill('This is a test message');

    // Wait for first auto-save (30 seconds)
    await page.waitForTimeout(31000);

    // Check for draft saved indicator
    const draftIndicator = page.getByText('Draft saved');
    await expect(draftIndicator).toBeVisible();

    // Verify draft was saved by checking localStorage or API call
    const savedDraft = await page.evaluate(() => {
      return localStorage.getItem('formDraft');
    });

    expect(savedDraft).toBeTruthy();
    const draftData = JSON.parse(savedDraft || '{}');
    expect(draftData.name).toBe('John Doe');
    expect(draftData.email).toBe('john@example.com');
    expect(draftData.message).toBe('This is a test message');
  });

  test('should update draft on subsequent auto-saves', async ({ page }) => {
    // Fill initial form data
    const nameInput = page.getByLabel('Name');
    const emailInput = page.getByLabel('Email');

    await nameInput.fill('Jane Smith');
    await emailInput.fill('jane@example.com');

    // Wait for first auto-save
    await page.waitForTimeout(31000);

    // Verify first save
    let savedDraft = await page.evaluate(() => {
      return localStorage.getItem('formDraft');
    });
    let draftData = JSON.parse(savedDraft || '{}');
    expect(draftData.name).toBe('Jane Smith');

    // Update form data
    await nameInput.fill('Jane Doe');
    const messageInput = page.getByLabel('Message');
    await messageInput.fill('Updated message');

    // Wait for second auto-save
    await page.waitForTimeout(31000);

    // Verify second save with updated data
    savedDraft = await page.evaluate(() => {
      return localStorage.getItem('formDraft');
    });
    draftData = JSON.parse(savedDraft || '{}');
    expect(draftData.name).toBe('Jane Doe');
    expect(draftData.message).toBe('Updated message');

    // Check that draft saved indicator appears again
    const draftIndicator = page.getByText('Draft saved');
    await expect(draftIndicator).toBeVisible();
  });

  test('should restore form from draft on page reload', async ({ page }) => {
    // Fill form with data
    const nameInput = page.getByLabel('Name');
    const emailInput = page.getByLabel('Email');
    const messageInput = page.getByLabel('Message');

    await nameInput.fill('Test User');
    await emailInput.fill('test@example.com');
    await messageInput.fill('Test message content');

    // Wait for auto-save
    await page.waitForTimeout(31000);

    // Verify draft was saved
    const draftIndicator = page.getByText('Draft saved');
    await expect(draftIndicator).toBeVisible();

    // Reload page
    await page.reload();
    await page.waitForLoadState('networkidle');

    // Verify form is restored from draft
    const restoredNameInput = page.getByLabel('Name');
    const restoredEmailInput = page.getByLabel('Email');
    const restoredMessageInput = page.getByLabel('Message');

    await expect(restoredNameInput).toHaveValue('Test User');
    await expect(restoredEmailInput).toHaveValue('test@example.com');
    await expect(restoredMessageInput).toHaveValue('Test message content');
  });

  test('should show draft saved notification at correct intervals', async ({ page }) => {
    const nameInput = page.getByLabel('Name');
    await nameInput.fill('Interval Test');

    // First auto-save at 30 seconds
    await page.waitForTimeout(31000);
    let draftIndicator = page.getByText('Draft saved');
    await expect(draftIndicator).toBeVisible();

    // Notification should disappear after a few seconds
    await page.waitForTimeout(3000);
    await expect(draftIndicator).not.toBeVisible();

    // Second auto-save at 60 seconds total
    await page.waitForTimeout(28000);
    draftIndicator = page.getByText('Draft saved');
    await expect(draftIndicator).toBeVisible();
  });

  test('should not auto-save if form has validation errors', async ({ page }) => {
    // Fill form with invalid data
    const emailInput = page.getByLabel('Email');
    await emailInput.fill('invalid-email');

    // Clear localStorage to track new saves
    await page.evaluate(() => {
      localStorage.removeItem('formDraft');
    });

    // Wait for auto-save interval
    await page.waitForTimeout(31000);

    // Check if validation error is displayed
    const errorMessage = page.getByText(/invalid email/i);
    const isErrorVisible = await errorMessage.isVisible().catch(() => false);

    if (isErrorVisible) {
      // If validation error exists, draft should not be saved
      const savedDraft = await page.evaluate(() => {
        return localStorage.getItem('formDraft');
      });
      expect(savedDraft).toBeNull();
    }
  });

  test('should clear draft after successful form submission', async ({ page }) => {
    // Fill form with valid data
    const nameInput = page.getByLabel('Name');
    const emailInput = page.getByLabel('Email');
    const messageInput = page.getByLabel('Message');

    await nameInput.fill('Submit Test');
    await emailInput.fill('submit@example.com');
    await messageInput.fill('Submission test');

    // Wait for auto-save
    await page.waitForTimeout(31000);

    // Verify draft exists
    let savedDraft = await page.evaluate(() => {
      return localStorage.getItem('formDraft');
    });
    expect(savedDraft).toBeTruthy();

    // Submit form
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Wait for submission to complete
    await page.waitForTimeout(2000);

    // Verify draft is cleared after successful submission
    savedDraft = await page.evaluate(() => {
      return localStorage.getItem('formDraft');
    });
    expect(savedDraft).toBeNull();
  });
});
